const $=s=>document.querySelector(s);const app=$('#app');const params=new URLSearchParams(location.search);let view=params.get('view')||'login';
const go=path=>{window.parent.location.hash=`#/contributor/${path}`};const publicGo=path=>{window.parent.location.hash=`#${path}`};
const toast=msg=>{const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)};
const currentUser={name:'สมใจ ใจดี',initials:'สจ',contributorType:'นวัตกรชุมชน/อาสาสมัครชุมชน',organization:'ชุมชนบ่อสร้าง',area:'ชุมชนบ่อสร้าง ตำบลต้นเปา',role:'นวัตกรชุมชน',email:'contributor@tonpao.local',verifier:'ประธานชุมชนบ่อสร้าง',verified:true};
const pois=[{id:1,name:'ศูนย์อุตสาหกรรมทำร่มบ่อสร้าง',cat:'หัตถกรรม',status:'revision',label:'ส่งกลับแก้ไข',updated:'วันนี้ 10:30',lat:18.7622,lng:99.0751},{id:2,name:'ร้านพัดกระดาษสาแม่บัวผัน',cat:'หัตถกรรม',status:'approved',label:'เผยแพร่แล้ว',updated:'18 ก.ย. 2569',lat:18.7648,lng:99.0728},{id:3,name:'บ้านไม้แกะสลักล้านนาต้นเปา',cat:'วัฒนธรรม',status:'pending',label:'รอตรวจสอบ',updated:'17 ก.ย. 2569',lat:18.7589,lng:99.0807},{id:4,name:'คาเฟ่ร่มไม้สันกำแพง',cat:'อาหารและคาเฟ่',status:'draft',label:'แบบร่าง',updated:'15 ก.ย. 2569',lat:18.7681,lng:99.0784}];
const icon={dashboard:'▦',pois:'⌖',new:'＋',notifications:'●',profile:'♙'};
function nav(){return `<aside class="sidebar"><div class="brand"><div class="mark">T</div><span>TonPao Map</span></div><nav class="nav" aria-label="เมนูผู้ร่วมให้ข้อมูล">${navItem('dashboard','แผงควบคุม')}${navItem('pois','สถานที่ของฉัน')}${navItem('pois/new','เพิ่มสถานที่')}${navItem('notifications','การแจ้งเตือน')}${navItem('profile','โปรไฟล์')}</nav><div class="sidebar-account"><div class="user-avatar">${currentUser.initials}</div><div class="sidebar-user-copy"><strong>${currentUser.name}</strong><span>${currentUser.role}</span></div></div><a href="#" class="nav logout" data-go="login">↩ <span>ออกจากระบบ</span></a></aside>`}
function navItem(path,label){const active=view===path||view.startsWith(path+'/');return `<a href="#" data-go="${path}" class="${active?'active':''}">${icon[path]||'•'} <span>${label}</span></a>`}
function mobileNav(){return `<nav class="mobile-nav" aria-label="เมนูผู้ร่วมให้ข้อมูลบนมือถือ">${[['dashboard','▦','หน้าหลัก'],['pois','⌖','สถานที่'],['pois/new','＋','เพิ่ม'],['notifications','●','แจ้งเตือน'],['profile','♙','โปรไฟล์']].map(([p,i,l])=>`<a href="#" data-go="${p}" class="${view===p?'active':''}"><b>${i}</b>${l}</a>`).join('')}</nav>`}
function shell(title,sub,content,actions=''){return `<div class="shell">${nav()}<main class="main"><header class="topbar"><div class="brand"><div class="mark">T</div><strong>พื้นที่ผู้ร่วมให้ข้อมูล</strong></div><div class="topbar-actions"><button class="btn btn-secondary notification-button" data-go="notifications" aria-label="การแจ้งเตือน">● 2</button><div class="account-menu"><button type="button" class="account-trigger" id="accountTrigger" aria-expanded="false" aria-controls="accountDropdown"><span class="user-avatar">${currentUser.initials}</span><span class="account-trigger-copy"><strong>${currentUser.name}</strong><small>${currentUser.role}</small></span><span aria-hidden="true">⌄</span></button><div class="account-dropdown" id="accountDropdown" hidden><div class="account-summary"><strong>${currentUser.name}</strong><span>${currentUser.organization}</span><small>${currentUser.email}</small></div><button type="button" data-go="profile">♙ ดูและแก้ไขโปรไฟล์</button><button type="button" data-go="change-password">▣ เปลี่ยนรหัสผ่าน</button><button type="button" class="logout-action" data-go="login">↩ ออกจากระบบ</button></div></div></div></header><div class="content"><div class="page-head"><div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="actions">${actions}</div></div>${content}</div></main>${mobileNav()}</div>`}
function auth(title,sub,form){return `<div class="auth"><section class="auth-art"><div class="brand"><div class="mark">T</div>TonPao Map</div><div class="auth-copy"><p>ร่วมดูแลข้อมูลชุมชนต้นเปา</p><h1>ข้อมูลที่ถูกต้อง<br>ทำให้ชุมชนถูกค้นพบ</h1><p>เพิ่มและปรับปรุงข้อมูลสถานที่ เพื่อให้นักท่องเที่ยวเข้าถึงเรื่องราว สินค้า และบริการของชุมชนได้ง่ายขึ้น</p></div><a href="#" data-public="/">← กลับสู่แผนที่สาธารณะ</a></section><main class="auth-main"><section class="card auth-card"><h1>${title}</h1><p class="sub">${sub}</p>${form}</section></main></div>`}
function field(label,type='text',value='',name=''){return `<div class="field"><label>${label}</label><input type="${type}" value="${value}" name="${name}" required></div>`}
const status=s=>`<span class="status ${s.status}">${s.label}</span>`;
function intro(){return `<div class="intro-page"><header class="intro-header"><a class="brand" href="#" data-public="/"><span class="mark">T</span><span>TonPao Map</span></a><div class="intro-actions"><button class="btn btn-link" data-public="/">กลับหน้าแผนที่</button><button class="btn btn-secondary" data-go="login">เข้าสู่ระบบ</button><button class="btn btn-primary" data-go="register">สมัครเป็น Contributor</button></div></header><main><section class="intro-hero"><div><span class="intro-kicker">พื้นที่ผู้ร่วมให้ข้อมูล</span><h1>ร่วมดูแลข้อมูลชุมชน<br>ให้ถูกต้องและเป็นปัจจุบัน</h1><p>Contributor คือผู้รู้จริงในพื้นที่ ซึ่งช่วยเสนอ เพิ่ม และปรับปรุงข้อมูลสถานที่ ก่อนส่งให้ผู้ดูแลระบบตรวจสอบและเผยแพร่สู่แผนที่สาธารณะ</p><div class="intro-cta"><button class="btn btn-primary" data-go="register">สมัครเป็น Contributor</button><button class="btn btn-secondary" data-go="login">มีบัญชีแล้ว เข้าสู่ระบบ</button></div></div><aside class="intro-highlight"><strong>Contributor ทำอะไรได้บ้าง</strong><ul><li>เพิ่ม POI และรายละเอียดที่เป็นประโยชน์</li><li>แก้ไขข้อมูลที่ตนเพิ่มหรือได้รับมอบหมาย</li><li>ติดตามสถานะและตอบกลับข้อเสนอแนะ</li><li>ดูแลข้อมูลเฉพาะพื้นที่รับผิดชอบ</li></ul><p>ข้อมูลทุกชิ้นต้องผ่าน Moderator ก่อนเผยแพร่</p></aside></section><section class="intro-section"><div class="section-title"><span>ใครสมัครได้บ้าง</span><h2>3 กลุ่มผู้ร่วมให้ข้อมูล</h2></div><div class="intro-types"><article><b>01</b><h3>ผู้ประกอบการ</h3><p>เจ้าของหรือผู้แทนสถานประกอบการ ดูแลข้อมูลกิจการและสถานที่ของตน</p></article><article><b>02</b><h3>ผู้แทนกลุ่มหรือวิสาหกิจชุมชน</h3><p>ดูแลข้อมูลของกลุ่ม ผลิตภัณฑ์ แหล่งเรียนรู้ และกิจกรรมของสมาชิก</p></article><article><b>03</b><h3>นวัตกรชุมชนหรืออาสาสมัคร</h3><p>ผู้ได้รับการรับรองจากชุมชน ช่วยรวบรวมและปรับปรุงข้อมูลในพื้นที่ที่รับผิดชอบ</p></article></div></section><section class="intro-section workflow"><div class="section-title"><span>ขั้นตอนสมัคร</span><h2>ยืนยันตัวตนก่อนเริ่มให้ข้อมูล</h2></div><ol><li><b>1</b><div><strong>กรอกคำขอ</strong><span>ระบุประเภท บทบาท และพื้นที่รับผิดชอบ</span></div></li><li><b>2</b><div><strong>ยืนยันช่องทางติดต่อ</strong><span>ยืนยันอีเมลหรือหมายเลขโทรศัพท์</span></div></li><li><b>3</b><div><strong>Admin ตรวจสอบ</strong><span>ตรวจตัวตน ผู้รับรอง และขอบเขตพื้นที่</span></div></li><li><b>4</b><div><strong>เริ่มส่งข้อมูล</strong><span>POI ยังต้องผ่าน Moderator ก่อนเผยแพร่</span></div></li></ol></section><section class="intro-bottom"><h2>พร้อมช่วยให้ชุมชนของคุณถูกค้นพบแล้วหรือยัง</h2><button class="btn btn-primary" data-go="register">เริ่มสมัคร Contributor</button></section></main></div>`}
function login(){return auth('เข้าสู่ระบบ','สำหรับผู้ประกอบการ ผู้แทนกลุ่ม และนวัตกรชุมชน',`<form data-submit="dashboard">${field('อีเมล','email','contributor@tonpao.local')}${field('รหัสผ่าน','password','12345678')}<div class="row"><label><input type="checkbox"> จดจำฉัน</label><a href="#" data-go="forgot-password">ลืมรหัสผ่าน</a></div><button class="btn btn-primary full">เข้าสู่ระบบ</button></form><p class="sub" style="text-align:center;margin-top:1rem">ยังไม่มีบัญชี <a href="#" data-go="register">สมัครเป็น Contributor</a></p>`)}
function register(){return auth('สมัครเป็น Contributor','เลือกประเภทผู้ร่วมให้ข้อมูลและระบุขอบเขตที่รับผิดชอบ',`<form data-submit="verify"><div class="field"><label>ประเภท Contributor *</label><select id="contributorType" required><option value="">เลือกประเภทผู้ใช้งาน</option><option>ผู้ประกอบการ/ผู้แทนสถานประกอบการ</option><option>ผู้แทนกลุ่ม/วิสาหกิจชุมชน</option><option selected>นวัตกรชุมชน/อาสาสมัครชุมชน</option></select><span class="help">ประเภทบัญชีใช้กำหนดข้อมูลและพื้นที่ที่คุณสามารถเสนอหรือแก้ไขได้</span></div><div class="grid form-grid">${field('ชื่อ–นามสกุล *','text','','name')}${field('อีเมล *','email','','email')}${field('หมายเลขโทรศัพท์ *','tel','','phone')}${field('ชุมชน/หน่วยงาน/สถานประกอบการ *','text','','org')}${field('ตำบล *','text','ต้นเปา','tambon')}${field('หมู่บ้านหรือชุมชนที่รับผิดชอบ *','text','','community')}${field('ชื่อผู้รับรองหรือผู้มอบหมาย *','text','','verifier')}${field('ตำแหน่งผู้รับรอง','text','','verifier_role')}<div class="field span2"><label>รายละเอียดขอบเขตพื้นที่รับผิดชอบ *</label><textarea required placeholder="ระบุชุมชน หมู่บ้าน หรือบริเวณที่ได้รับมอบหมายให้รวบรวมข้อมูล"></textarea></div><div class="span2">${field('รหัสผ่าน *','password','','password')}</div></div><div class="verification-note"><strong>การตรวจสอบบัญชี</strong><p>บัญชีนวัตกรชุมชนจะใช้งานได้หลังจาก Moderator หรือ Admin ตรวจสอบผู้รับรองและพื้นที่รับผิดชอบแล้ว</p></div><label><input type="checkbox" required> ยอมรับ <a href="#" data-public="/terms">เงื่อนไขการใช้งาน</a> และ <a href="#" data-public="/privacy">นโยบายความเป็นส่วนตัว</a></label><button class="btn btn-primary full">ส่งคำขอลงทะเบียน</button></form><p class="sub" style="text-align:center;margin-top:1rem">มีบัญชีแล้ว <a href="#" data-go="login">เข้าสู่ระบบ</a></p>`)}
function messagePage(title,text,button,next){return auth(title,text,`<div class="card panel" style="box-shadow:none;text-align:center"><div style="font-size:3rem">✉</div><p>contributor@tonpao.local</p></div><button class="btn btn-primary full" data-go="${next}">${button}</button><button class="btn btn-link full" data-go="login">กลับสู่หน้าเข้าสู่ระบบ</button>`)}
function applicationStatus(){return auth('สถานะคำขอสมัคร','ส่งคำขอเรียบร้อยแล้ว คุณยังไม่สามารถเข้าแผงควบคุมได้จนกว่า Admin จะอนุมัติ',`<div class="application-summary"><div class="pending-icon">⌛</div><div><span class="status pending">รอ Admin ตรวจสอบ</span><h2>คำขอ Contributor</h2><p>ส่งเมื่อ 19 ก.ย. 2569 · เลขที่คำขอ CT-2569-0042</p></div></div><dl class="application-details"><div><dt>ประเภท Contributor</dt><dd>นวัตกรชุมชน/อาสาสมัครชุมชน</dd></div><div><dt>พื้นที่รับผิดชอบ</dt><dd>ชุมชนบ่อสร้าง ตำบลต้นเปา</dd></div><div><dt>ผู้รับรอง</dt><dd>ประธานชุมชนบ่อสร้าง</dd></div></dl><ol class="approval-timeline"><li class="done"><b>✓</b><div><strong>ส่งคำขอและยืนยันช่องทางติดต่อแล้ว</strong><span>ระบบได้รับข้อมูลของคุณเรียบร้อย</span></div></li><li class="current"><b>2</b><div><strong>Admin ตรวจสอบตัวตนและพื้นที่</strong><span>อาจติดต่อผู้สมัครหรือผู้รับรองเพื่อขอข้อมูลเพิ่มเติม</span></div></li><li><b>3</b><div><strong>เปิดสิทธิ์ Contributor</strong><span>ระบบจะแจ้งผลทางอีเมลและการแจ้งเตือน</span></div></li></ol><div class="verification-note"><strong>ระยะเวลาดำเนินการโดยประมาณ 1–3 วันทำการ</strong><p>การอนุมัติบัญชีไม่เท่ากับการอนุมัติ POI ข้อมูลสถานที่แต่ละรายการยังต้องผ่าน Moderator ก่อนเผยแพร่</p></div><button class="btn btn-secondary full" data-go="register">แก้ไขข้อมูลคำขอ</button><button class="btn btn-link full" data-public="/">กลับสู่แผนที่สาธารณะ</button>`)}
function dashboard(){const cards=pois.slice(0,3).map(p=>`<div class="notice ${p.status==='revision'?'urgent':''}"><div class="row"><strong>${p.name}</strong>${status(p)}</div><p class="sub">อัปเดต ${p.updated}</p><div class="actions"><button class="btn btn-secondary" data-go="${p.status==='revision'?'pois/edit':'pois'}">${p.status==='revision'?'แก้ไขข้อมูล':'ดูรายละเอียด'}</button></div></div>`).join('');return shell('แผงควบคุม','ภาพรวมสถานที่และสถานะการตรวจสอบ',`<div class="grid kpis"><div class="card kpi"><span>สถานที่ทั้งหมด</span><strong>4</strong></div><div class="card kpi"><span>เผยแพร่แล้ว</span><strong>1</strong></div><div class="card kpi"><span>รอตรวจสอบ</span><strong>1</strong></div><div class="card kpi"><span>ต้องแก้ไข</span><strong>1</strong></div></div><section class="card panel contributor-map-panel"><div class="map-panel-head"><div><h2>แผนที่สถานที่ของฉัน</h2><p class="sub">แสดงเฉพาะสถานที่ที่คุณเพิ่มหรือได้รับสิทธิ์ดูแล รวมทั้งรายการที่ยังไม่เผยแพร่</p></div><div class="map-filters"><select id="mapStatusFilter" aria-label="กรองสถานะบนแผนที่"><option value="all">ทุกสถานะ</option><option value="approved">เผยแพร่แล้ว</option><option value="pending">รอตรวจสอบ</option><option value="revision">ต้องแก้ไข</option><option value="draft">แบบร่าง</option></select><select id="mapCategoryFilter" aria-label="กรองหมวดหมู่บนแผนที่"><option value="all">ทุกหมวดหมู่</option>${[...new Set(pois.map(p=>p.cat))].map(c=>`<option value="${c}">${c}</option>`).join('')}</select><button type="button" class="btn btn-secondary" id="fitAllPois">แสดงทั้งหมด</button></div></div><div class="map-legend" aria-label="คำอธิบายสถานะ"><span><i class="legend-dot approved-dot"></i>เผยแพร่แล้ว</span><span><i class="legend-dot pending-dot"></i>รอตรวจสอบ</span><span><i class="legend-dot revision-dot"></i>ต้องแก้ไข</span><span><i class="legend-dot draft-dot"></i>แบบร่าง</span></div><div id="contributorMap" aria-label="แผนที่สถานที่ของผู้ร่วมให้ข้อมูล"></div><p id="mapResultCount" class="map-result-count" aria-live="polite"></p></section><div class="grid two" style="margin-top:1rem"><section class="card panel"><h2>รายการล่าสุด</h2>${cards}</section><aside class="card panel"><h2>งานที่ทำได้ทันที</h2><div class="stack"><button class="btn btn-primary" data-go="pois/new">＋ เพิ่มสถานที่ใหม่</button><button class="btn btn-secondary" data-go="pois">จัดการสถานที่ทั้งหมด</button><button class="btn btn-secondary" data-public="/map">ดูแผนที่สาธารณะ</button></div></aside></div>`,`<button class="btn btn-primary" data-go="pois/new">＋ เพิ่มสถานที่</button>`)}

function initContributorMap(){const node=document.querySelector('#contributorMap');if(!node||typeof L==='undefined')return;const colors={approved:'#15803d',pending:'#d97706',revision:'#dc2626',draft:'#64748b'};const map=L.map(node,{zoomControl:true,scrollWheelZoom:false}).setView([18.7634,99.0765],15);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);const layer=L.layerGroup().addTo(map);const statusFilter=document.querySelector('#mapStatusFilter');const categoryFilter=document.querySelector('#mapCategoryFilter');const count=document.querySelector('#mapResultCount');const fit=items=>{if(!items.length)return;const bounds=L.latLngBounds(items.map(p=>[p.lat,p.lng]));map.fitBounds(bounds.pad(.25),{maxZoom:16})};const draw=()=>{layer.clearLayers();const visible=pois.filter(p=>(statusFilter.value==='all'||p.status===statusFilter.value)&&(categoryFilter.value==='all'||p.cat===categoryFilter.value));visible.forEach(p=>{const icon=L.divIcon({className:'poi-marker-wrap',html:`<span class="poi-marker" style="--marker:${colors[p.status]}"><b>⌖</b></span>`,iconSize:[38,38],iconAnchor:[19,36],popupAnchor:[0,-34]});const actions=`<button type="button" onclick="window.parent.location.hash='#/contributor/pois/edit'">แก้ไขข้อมูล</button>${p.status==='approved'?`<button type="button" class="popup-secondary" onclick="window.parent.location.hash='#/poi/umbrella-center'">ดูหน้าสาธารณะ</button>`:''}`;L.marker([p.lat,p.lng],{icon}).bindPopup(`<div class="poi-popup"><span class="popup-status ${p.status}">${p.label}</span><h3>${p.name}</h3><p>${p.cat} · อัปเดต ${p.updated}</p><div class="popup-actions">${actions}</div></div>`).addTo(layer)});count.textContent=`แสดง ${visible.length} จาก ${pois.length} สถานที่`;if(visible.length)fit(visible)};statusFilter.addEventListener('change',draw);categoryFilter.addEventListener('change',draw);document.querySelector('#fitAllPois').addEventListener('click',()=>{statusFilter.value='all';categoryFilter.value='all';draw()});draw();setTimeout(()=>map.invalidateSize(),50)}
function poisView(){const rows=pois.map(p=>`<tr><td><strong>${p.name}</strong><br><span class="sub">${p.cat}</span></td><td>${status(p)}</td><td>${p.updated}</td><td><button class="btn btn-secondary" data-go="pois/edit">แก้ไข</button> <button class="btn btn-link" data-public="/poi/umbrella-center">ดูตัวอย่าง</button></td></tr>`).join('');const cards=pois.map(p=>`<article class="card poi-card"><div class="row"><strong>${p.name}</strong>${status(p)}</div><p class="sub">${p.cat} · ${p.updated}</p><div class="actions"><button class="btn btn-secondary" data-go="pois/edit">แก้ไข</button><button class="btn btn-link" data-public="/poi/umbrella-center">ดูตัวอย่าง</button></div></article>`).join('');return shell('สถานที่ของฉัน','จัดการข้อมูลและติดตามสถานะการตรวจสอบ',`<div class="filters"><input aria-label="ค้นหาสถานที่" placeholder="ค้นหาชื่อสถานที่…"><select aria-label="กรองสถานะ"><option>ทุกสถานะ</option><option>เผยแพร่แล้ว</option><option>รอตรวจสอบ</option><option>แบบร่าง</option></select></div><section class="card panel"><div class="table-wrap"><table class="poi-table"><thead><tr><th>สถานที่</th><th>สถานะ</th><th>แก้ไขล่าสุด</th><th>การทำงาน</th></tr></thead><tbody>${rows}</tbody></table></div><div class="poi-cards">${cards}</div></section>`,`<button class="btn btn-primary" data-go="pois/new">＋ เพิ่มสถานที่</button>`)}
function poiForm(edit=false){
  const title=edit?'แก้ไขสถานที่':'เพิ่มสถานที่ใหม่';
  const v=(text='')=>edit?text:'';
  const revision=edit?`<div class="notice urgent"><strong>ข้อเสนอแนะจากผู้ตรวจ</strong><p>กรุณาเพิ่มภาพป้ายหน้าร้าน ระบุเวลาเปิดในวันหยุด และตรวจสอบพิกัดบนแผนที่</p></div>`:'';
  const categories=`<div class="field"><label>หมวดหมู่หลัก *</label><select required><option value="">เลือกหมวดหมู่</option><option selected>หัตถกรรมและร่มบ่อสร้าง</option><option>วัดและวัฒนธรรม</option><option>อาหารและคาเฟ่</option><option>แหล่งเรียนรู้ชุมชน</option><option>ที่พัก</option></select><span class="help">กิจกรรมและเทศกาลจัดการด้วยแบบฟอร์มกิจกรรมแยกต่างหาก</span></div>`;
  const facilities=['ที่จอดรถ','ห้องน้ำ','รองรับรถเข็น','Wi-Fi','รับชำระเงินดิจิทัล','เหมาะสำหรับเด็ก','พื้นที่ในร่ม','เหมาะกับวันฝนตก'].map(x=>`<label class="check"><input type="checkbox" ${edit&&['ที่จอดรถ','ห้องน้ำ','พื้นที่ในร่ม','เหมาะกับวันฝนตก'].includes(x)?'checked':''}> <span>${x}</span></label>`).join('');
  const dayHours=[
    ['วันจันทร์','open'],['วันอังคาร','open'],['วันพุธ','open'],['วันพฤหัสบดี','open'],
    ['วันศุกร์','open'],['วันเสาร์','open'],['วันอาทิตย์',edit?'closed':'open'],['วันหยุดนักขัตฤกษ์',edit?'closed':'open']
  ];
  const weekdays=dayHours.map(([d,state])=>`<div class="weekday" data-hours-row><strong>${d}</strong><select data-hours-status aria-label="สถานะการเปิด ${d}"><option value="open" ${state==='open'?'selected':''}>เปิดตามเวลา</option><option value="closed" ${state==='closed'?'selected':''}>ปิดประจำ</option><option value="24h">เปิด 24 ชั่วโมง</option></select><div class="time-range"><input type="time" data-hours-time aria-label="เวลาเปิด ${d}" value="${edit&&state==='open'?'08:30':''}"><span aria-hidden="true">ถึง</span><input type="time" data-hours-time aria-label="เวลาปิด ${d}" value="${edit&&state==='open'?'17:00':''}"></div></div>`).join('');
  return shell(title,edit?'ปรับข้อมูลและส่งตรวจสอบอีกครั้ง':'ข้อมูลเหล่านี้จะใช้สร้างการ์ด หมุดแผนที่ และหน้ารายละเอียดใน Public',`${revision}<section class="card panel"><div class="required-note">ช่องที่มีเครื่องหมาย * จำเป็นต่อการเผยแพร่ใน Public Prototype</div><div class="wizard" aria-label="4 ขั้นตอน"><i class="step on"></i><i class="step on"></i><i class="step on"></i><i class="step on"></i></div><form data-save="pois">
    <section class="form-section"><h2><span class="step-label">1</span>ข้อมูลพื้นฐานและเนื้อหาสำหรับ Public</h2><p class="help">ใช้แสดงบนการ์ด ผลการค้นหา และหน้ารายละเอียดสถานที่</p><div class="grid form-grid">${field('ชื่อสถานที่ *','text',v('ศูนย์อุตสาหกรรมทำร่มบ่อสร้าง'))}${categories}${field('หมวดหมู่ย่อย','text',v('ศูนย์เรียนรู้และสาธิตงานหัตถกรรม'))}${field('ชื่อสำหรับ URL (Slug)','text',v('umbrella-center'))}<div class="field span2"><label>คำอธิบายสั้นสำหรับการ์ด * <span class="help">ไม่เกิน 160 ตัวอักษร</span></label><textarea maxlength="160" required>${v('เรียนรู้การผลิตร่มบ่อสร้างและเลือกชมงานหัตถกรรมจากช่างฝีมือในชุมชนต้นเปา')}</textarea></div><div class="field span2"><label>รายละเอียดสถานที่ *</label><textarea required>${v('แหล่งเรียนรู้กระบวนการผลิตร่มบ่อสร้าง ตั้งแต่การเตรียมโครงร่ม การปิดกระดาษสา ไปจนถึงการวาดลวดลาย')}</textarea></div><div class="field span2"><label>เรื่องราวและจุดเด่น</label><textarea>${v('ภูมิปัญญาการทำร่มที่สืบทอดจากช่างฝีมือท้องถิ่นและเป็นอัตลักษณ์สำคัญของชุมชนต้นเปา')}</textarea></div><div class="field span2"><label>สินค้าและบริการเด่น</label><textarea>${v('ร่มบ่อสร้าง กระดาษสา ของที่ระลึก และกิจกรรมทดลองวาดร่ม')}</textarea></div></div></section>
    <section class="form-section"><h2><span class="step-label">2</span>ที่ตั้งและพิกัดแผนที่</h2><p class="help">ใช้สร้างหมุดบน Leaflet + OpenStreetMap และปุ่มนำทาง</p><div class="grid form-grid">${field('บ้านเลขที่/ถนน *','text',v('111/2 ถนนเชียงใหม่–สันกำแพง'))}${field('ตำบล *','text',v('ต้นเปา'))}${field('อำเภอ *','text',v('สันกำแพง'))}${field('จังหวัด *','text',v('เชียงใหม่'))}${field('รหัสไปรษณีย์ *','text',v('50130'))}${field('จุดสังเกตใกล้เคียง','text',v('ใกล้สี่แยกบ่อสร้าง'))}${field('ละติจูด *','number',v('18.7618'))}${field('ลองจิจูด *','number',v('99.0746'))}<div class="span2 map-box"><div><strong>แผนที่เลือกตำแหน่ง</strong><p>ลากหมุดหรือใช้ตำแหน่งปัจจุบันเพื่อกำหนดพิกัด</p><button type="button" class="btn btn-secondary" data-map-pin>ใช้ตำแหน่งตัวอย่าง</button></div></div><div class="field span2"><label>คำแนะนำการเดินทาง</label><textarea>${v('เดินทางจากตัวเมืองเชียงใหม่ตามถนนสายเชียงใหม่–สันกำแพงประมาณ 9 กิโลเมตร')}</textarea></div></div></section>
    <section class="form-section"><h2><span class="step-label">3</span>เวลาเปิด–ปิด การติดต่อ และสิ่งอำนวยความสะดวก</h2><p class="help">กำหนดแต่ละวันแยกกัน หากร้านหยุดประจำวันใดให้เลือก “ปิดประจำ” ระบบจะนำข้อมูลไปแสดงในหน้าสาธารณะตามรายการนี้</p><div class="hours-head" aria-hidden="true"><span>วัน</span><span>สถานะ</span><span>เวลาเปิด–ปิด</span></div><div class="weekday-grid">${weekdays}</div><div class="grid form-grid">${field('โทรศัพท์','tel',v('053-000-000'))}${field('LINE ID','text',v('@tonpao-umbrella'))}${field('Facebook','url',v('https://facebook.com/tonpaoumbrella'))}${field('เว็บไซต์','url',v('https://example.com'))}${field('อีเมล','email',v('contact@example.com'))}${field('ช่วงราคา/ค่าเข้าชม','text',v('เข้าชมฟรี กิจกรรมเริ่มต้น 100 บาท'))}<div class="field span2"><label>สถานะการให้บริการ</label><select><option>เปิดให้บริการตามปกติ</option><option>ปิดชั่วคราว</option><option>เปิดเฉพาะการจองล่วงหน้า</option></select></div><div class="span2"><strong>สิ่งอำนวยความสะดวกและความเหมาะสม</strong><div class="check-grid" style="margin-top:.6rem">${facilities}</div></div></div></section>
    <section class="form-section"><h2><span class="step-label">4</span>รูปภาพ สิทธิ์การใช้งาน และการส่งตรวจ</h2><div class="grid form-grid"><div class="field"><label>ภาพปก *</label><input type="file" accept="image/*" required><span class="help">ใช้บนการ์ดและส่วนหัวของหน้ารายละเอียด</span></div><div class="field"><label>ภาพแกลเลอรี</label><input type="file" accept="image/*" multiple><span class="help">แนะนำ 3–8 ภาพ</span></div>${field('คำอธิบายภาพปก (Alt text) *','text',v('ช่างฝีมือกำลังวาดลวดลายบนร่มบ่อสร้าง'))}<div class="field"><label>แหล่งที่มาของภาพ</label><input value="${v('ภาพถ่ายโดยผู้ประกอบการ')}" placeholder="ชื่อผู้ถ่ายหรือหน่วยงาน"></div><div class="span2"><label class="check"><input type="checkbox" ${edit?'checked':''} required> <span>ข้าพเจ้ามีสิทธิ์ใช้และอนุญาตให้เผยแพร่ภาพและข้อมูลนี้บน TonPao Map *</span></label></div></div></section>
    <div class="actions"><button type="button" class="btn btn-secondary" data-go="pois">ยกเลิก</button><button type="button" class="btn btn-secondary" data-save-action="draft">บันทึกแบบร่าง</button><button class="btn btn-primary">${edit?'ส่งตรวจสอบอีกครั้ง':'ส่งข้อมูลให้ตรวจสอบ'}</button>${edit?'<button type="button" class="btn btn-link" data-public="/poi/umbrella-center">ดูตัวอย่างหน้าสาธารณะ</button>':''}</div></form></section>`)
}
function profile(){return shell('โปรไฟล์ Contributor','ข้อมูลตัวตน ประเภทผู้ใช้งาน และขอบเขตพื้นที่รับผิดชอบ',`<section class="card panel"><div class="profile-status"><div><span class="eyebrow">ประเภท Contributor</span><h2>${currentUser.contributorType}</h2><p>${currentUser.role} · ${currentUser.organization}</p></div><span class="verified-badge">✓ ยืนยันตัวตนแล้ว</span></div><form data-save="profile"><div class="grid form-grid">${field('ชื่อ–นามสกุล','text',currentUser.name)}<div class="field"><label>ประเภท Contributor</label><select><option>ผู้ประกอบการ/ผู้แทนสถานประกอบการ</option><option>ผู้แทนกลุ่ม/วิสาหกิจชุมชน</option><option selected>นวัตกรชุมชน/อาสาสมัครชุมชน</option></select></div>${field('อีเมล','email',currentUser.email)}${field('โทรศัพท์','tel','089-000-0000')}${field('ชุมชน/หน่วยงาน','text',currentUser.organization)}${field('ตำบล','text','ต้นเปา')}${field('พื้นที่รับผิดชอบ','text',currentUser.area)}${field('ผู้รับรอง/ผู้มอบหมาย','text',currentUser.verifier)}<div class="field span2"><label>รายละเอียดขอบเขตการจัดการข้อมูล</label><textarea>เพิ่มและปรับปรุงข้อมูลสถานที่สาธารณะ ภูมิปัญญา แหล่งเรียนรู้ และกิจกรรมภายในชุมชนบ่อสร้าง รายการทั้งหมดต้องผ่าน Moderator ก่อนเผยแพร่</textarea></div></div><div class="permission-summary span2"><strong>สิทธิ์ของบัญชีนี้</strong><div class="permission-grid"><span>✓ เพิ่ม POI ในพื้นที่รับผิดชอบ</span><span>✓ แก้ไขข้อมูลที่ตนเพิ่มหรือได้รับมอบหมาย</span><span>✓ ติดตามสถานะการตรวจสอบ</span><span class="not-allowed">– ไม่มีสิทธิ์อนุมัติหรือเผยแพร่เอง</span></div></div><button class="btn btn-primary">บันทึกการเปลี่ยนแปลง</button></form></section>`)}
function changePassword(){return shell('เปลี่ยนรหัสผ่าน','ตั้งรหัสผ่านใหม่สำหรับบัญชีของคุณ',`<section class="card panel narrow-panel"><form data-save="profile">${field('รหัสผ่านปัจจุบัน','password','')}${field('รหัสผ่านใหม่','password','')}${field('ยืนยันรหัสผ่านใหม่','password','')}<p class="help">รหัสผ่านต้องมีอย่างน้อย 8 ตัวอักษร</p><div class="actions"><button type="button" class="btn btn-secondary" data-go="dashboard">ยกเลิก</button><button class="btn btn-primary">บันทึกรหัสผ่านใหม่</button></div></form></section>`)}
function notifications(){return shell('การแจ้งเตือน','ติดตามผลตรวจสอบและข่าวสารที่เกี่ยวข้อง',`<section class="card panel"><article class="notice urgent"><div class="row"><strong>สถานที่ถูกส่งกลับให้แก้ไข</strong><span class="status revision">ยังไม่ได้อ่าน</span></div><h3>ศูนย์อุตสาหกรรมทำร่มบ่อสร้าง</h3><p>กรุณาเพิ่มภาพป้ายหน้าร้านและเวลาเปิดในวันหยุดนักขัตฤกษ์</p><button class="btn btn-primary" data-go="pois/edit">แก้ไขรายการ</button></article><article class="notice"><div class="row"><strong>อนุมัติและเผยแพร่แล้ว</strong><span class="status approved">อ่านแล้ว</span></div><h3>ร้านพัดกระดาษสาแม่บัวผัน</h3><p>ข้อมูลพร้อมแสดงบนแผนที่สาธารณะแล้ว</p><button class="btn btn-secondary" data-public="/poi/umbrella-center">ดูหน้าสาธารณะ</button></article></section>`)}
function render(){const map={intro,login,register,'verify':()=>messagePage('ยืนยันอีเมล','เราได้ส่งลิงก์ยืนยันไปยังอีเมลของคุณ','ยืนยันอีเมลและติดตามสถานะ','application-status'),'application-status':applicationStatus,'forgot-password':()=>auth('ลืมรหัสผ่าน','กรอกอีเมลเพื่อรับลิงก์ตั้งรหัสผ่านใหม่',`<form data-submit="reset-password">${field('อีเมล','email','contributor@tonpao.local')}<button class="btn btn-primary full">ส่งคำขอ</button></form><button class="btn btn-link full" data-go="login">กลับสู่หน้าเข้าสู่ระบบ</button>`),'reset-password':()=>auth('ตั้งรหัสผ่านใหม่','กำหนดรหัสผ่านอย่างน้อย 8 ตัวอักษร',`<form data-submit="login">${field('รหัสผ่านใหม่','password','')}${field('ยืนยันรหัสผ่าน','password','')}<button class="btn btn-primary full">บันทึกรหัสผ่านใหม่</button></form>`),dashboard,'pois':poisView,'pois/new':()=>poiForm(false),'pois/edit':()=>poiForm(true),profile,'change-password':changePassword,notifications};app.innerHTML=(map[view]||intro)();bind();initContributorMap()}
function bind(){document.querySelectorAll('[data-go]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();go(el.dataset.go)}));document.querySelectorAll('[data-public]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();publicGo(el.dataset.public)}));document.querySelectorAll('form[data-submit]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();toast('ดำเนินการสำเร็จ');setTimeout(()=>go(f.dataset.submit),350)}));document.querySelectorAll('form[data-save]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();localStorage.setItem('tonpao-contributor-updated',new Date().toISOString());toast('บันทึกข้อมูลแล้ว');setTimeout(()=>go(f.dataset.save),500)}));document.querySelectorAll('[data-save-action]').forEach(b=>b.addEventListener('click',()=>{localStorage.setItem('tonpao-contributor-draft','1');toast('บันทึกแบบร่างแล้ว');setTimeout(()=>go('pois'),500)}));document.querySelectorAll('[data-map-pin]').forEach(b=>b.addEventListener('click',()=>toast('กำหนดพิกัดตัวอย่างแล้ว')));document.querySelectorAll('[data-hours-row]').forEach(row=>{const status=row.querySelector('[data-hours-status]');const times=[...row.querySelectorAll('[data-hours-time]')];const sync=()=>{const closed=status.value==='closed',allDay=status.value==='24h';times.forEach((input,i)=>{input.disabled=closed||allDay;if(closed)input.value='';if(allDay)input.value=i?'23:59':'00:00'})};status.addEventListener('change',sync);sync()})}
function bindAccountMenu(){const trigger=document.querySelector('#accountTrigger'),dropdown=document.querySelector('#accountDropdown');if(!trigger||!dropdown)return;const close=()=>{dropdown.hidden=true;trigger.setAttribute('aria-expanded','false')};trigger.addEventListener('click',e=>{e.stopPropagation();const willOpen=dropdown.hidden;dropdown.hidden=!willOpen;trigger.setAttribute('aria-expanded',String(willOpen))});dropdown.addEventListener('click',e=>e.stopPropagation());document.addEventListener('click',close);document.addEventListener('keydown',e=>{if(e.key==='Escape')close()})}
function personalizeDashboard(){if(view!=='dashboard')return;const head=document.querySelector('.page-head'),title=document.querySelector('.page-head h1'),sub=document.querySelector('.page-head .sub');if(title)title.textContent=`สวัสดี ${currentUser.name}`;if(sub)sub.textContent=`${currentUser.contributorType} · ${currentUser.organization}`;if(head)head.insertAdjacentHTML('afterend',`<section class="scope-banner"><div><span class="eyebrow">พื้นที่รับผิดชอบ</span><strong>${currentUser.area}</strong><p>คุณสามารถเพิ่มหรือแก้ไขข้อมูลที่ตนสร้างและรายการที่ได้รับมอบหมาย ข้อมูลทุกชิ้นต้องผ่าน Moderator ก่อนเผยแพร่</p></div><span class="verified-badge">✓ ยืนยันตัวตนแล้ว</span></section>`)}
render();bindAccountMenu();personalizeDashboard();
